function modalNotify(text) {
	$("#popup-notify").find(".modal-body").html(text);
	$('#popup-notify').modal('show');
}

function ValidationFormSelf(ele = '') {
	if (ele) {
		$("." + ele).find("input[type=submit]").removeAttr("disabled");
		var forms = document.getElementsByClassName(ele);
		var validation = Array.prototype.filter.call(forms, function (form) {
			form.addEventListener('submit', function (event) {
				if (form.checkValidity() === false) {
					event.preventDefault();
					event.stopPropagation();
				}
				form.classList.add('was-validated');
			}, false);
		});
	}
}

function loadPagingAjax(url = '', eShow = '') {
	if ($(eShow).length && url) {
		$.ajax({
			url: url,
			type: "GET",
			async: true,
			data: {
				eShow: eShow
			},
			success: function (result) {
				$(eShow).html(result);
			}
		});
	}
}

function doEnter(event, obj) {
	if (event.keyCode == 13 || event.which == 13) onSearch(obj);
}

function onSearch(obj) {
	var keyword = $("#" + obj).val();
	if (keyword == '') {
		modalNotify(LANG['no_keywords']);
		return false;
	} else {
		location.href = "san-pham?keyword=" + encodeURI(keyword);
		loadPage(document.location);
	}
}

function goToByScroll(id) {
	var offsetMenu = 0;
	id = id.replace("#", "");
	if ($("#menu").length) offsetMenu = $("#menu").height();
	$('html,body').animate({
		scrollTop: $("#" + id).offset().top - (offsetMenu * 2)
	}, 'slow');
}

function load_district(id = 0) {
	$.ajax({
		type: 'post',
		async: true,
		url: 'ajax/ajax_district.php',
		data: {
			id_city: id
		},
		success: function (result) {
			$(".select-district").html(result);
			$(".select-wards").html('<option value="">' + LANG['wards'] + '</option>');
			$('.select2').each(function () {
				const id = $(this).attr("id");
				$("#" + id).select2();
			});
		}
	});
}
function payment_account(id) {
	holdonOpen("sk-rect", "Vui lòng chờ...", "rgba(0,0,0,0.8)", "white");
	const url__submit = '/model/buy/account';
	$.ajax({
		url: url__submit,
		type: 'POST',
		data: {
			id: id,
			csrf_token: csrf_token
		},
		success: function (res) {
			const result = JSON.parse(res);
			holdonClose();
			if (result.status == "success") {
				alertSuccess(result.msg, "Hệ thống sẽ load lại trang sau vài giây");
				setTimeout("location.href = '/customer/nicks';", 2000);
			} else {
				alertDancer("Thông báo hệ thống", result.msg);
			}
		}.bind(this),
	});
}
function load_wards(id = 0) {
	$.ajax({
		type: 'post',
		async: true,
		url: 'ajax/ajax_wards.php',
		data: {
			id_district: id
		},
		success: function (result) {
			$(".select-wards").html(result);
			$('.select2').each(function () {
				const id = $(this).attr("id");
				$("#" + id).select2();
			});
		}
	});
}

function hasClass(ele, cls) {
	return !!ele.className.match(new RegExp('(\\s|^)' + cls + '(\\s|$)'));
}

function addClass(ele, cls) {
	if (!hasClass(ele, cls)) ele.className += " " + cls;
}

function removeClass(ele, cls) {
	if (hasClass(ele, cls)) {
		var reg = new RegExp('(\\s|^)' + cls + '(\\s|$)');
		ele.className = ele.className.replace(reg, ' ');
	}
}

function toggle_loadding() {
	if ($('.loadding-page').exists()) {
		var ele = document.getElementsByClassName("loadding-page")[0];
		if (!hasClass(ele, "d-none")) {
			addClass(ele, "d-none");
			removeClass(ele, "d-flex");
		} else {
			removeClass(ele, "d-none");
			addClass(ele, "d-flex");
		}
	}
}
async function removeAct(type, title, message, extra, button, table, id, box) {
	MSalert.principal({
		icon: type,
		title: title,
		description: message,
		extra: extra,
		button: button,
	}).then(result => {
		if (result == true) {
			$.ajax({
				url: 'ajax/ajax_removeRows.php',
				type: "POST",
				async: true,
				data: {
					id: id,
					table: table
				},
				success: function (result) {
					$("#" + box).remove();
					alertSuccess(LANG['tingting'], LANG['updatesuccess']);
				}
			});
		};
	});
};

