function getCart() {
	$.ajax({
		url: 'ajax/ajax_cart.php',
		type: "POST",
		dataType: 'html',
		async: true,
		data: {
			cmd: 'popup-cart'
		},
		success: function (result) {
			$(".content-cart").html(result);
		}
	});
}

function getOrder() {
	$.ajax({
		url: 'ajax/ajax_cart.php',
		type: "POST",
		dataType: 'html',
		async: true,
		data: {
			cmd: 'get-order'
		},
		success: function (result) {
			$(".order-cart").html(result);
		}
	});
}

function updateQtyCart(code, quantity, code) {
	$.ajax({
		url: 'ajax/ajax_cart.php',
		type: "POST",
		async: true,
		data: {
			cmd: 'update-cart',
			code: code,
			quantity: quantity
		},
		success: function (result) {
			if ($(".form-cart").exists()) {
				$(".form-cart").removeClass("loadding");
			}
			if ($(".form-order").exists()) {
				$(".form-order").removeClass("loadding");
			}
			getCart();
			getOrder();
			getTotalCart();
		}
	});
}

function getTotalCart() {
	$.ajax({
		url: 'ajax/ajax_cart.php',
		type: "POST",
		dataType: 'json',
		async: true,
		data: {
			cmd: 'total-cart'
		},
		success: function (result) {
			$('.total_cart').html(result.result);
			$('.result_order').html(result.result);
			$('.total_order').html(result.total);
			$('.total_order_giam').html(result.total_giam);
			$('.count-cart').html(result.count);
			const giamgia = $(".load-price-coupons").attr("data-coupons");
			$(".total_sum_cart").html((result.value - giamgia).toLocaleString('en-US'));
			$("#cart").removeClass("loaddding");
		}
	});
}

function toggleCart() {
	getCart();
	getTotalCart();
	var ele = document.getElementsByTagName('body')[0];
	if (!hasClass(ele, "open-cart")) {
		addClass(ele, "open-cart");
	} else {
		removeClass(ele, "open-cart");
	}
}

function toggleMenu() {
	var ele = document.getElementsByTagName('body')[0];
	if (!hasClass(ele, "open-menu")) {
		addClass(ele, "open-menu");
	} else {
		removeClass(ele, "open-menu");
	}
}

function setCookie(key, value, expiry) {
	var expires = new Date();
	expires.setTime(expires.getTime() + (expiry * 24 * 60 * 60 * 1000));
	document.cookie = key + '=' + value + ';expires=' + expires.toUTCString();
}

function getCookie(key) {
	var keyValue = document.cookie.match('(^|;) ?' + key + '=([^;]*)(;|$)');
	return keyValue ? keyValue[2] : null;
}

function eraseCookie(key) {
	var keyValue = getCookie(key);
	setCookie(key, keyValue, '-1');
}

