function notifyDialog(text) {
	let content = $(`<div class="content-popup-nguyennhieu w-400"><div class="header-popup-confirm"> <div class="icon-popup-nguyennhieu" style="--color: #026AA2"> <img src="data:image/svg+xml;base64," /> </div> <button type="button" class="close-popup-nguyennhieu" data-dismiss="modal" aria-label="Close"> &times; </button> </div> <div class="main-popup-confirm"> <h3>${text}</h3> <p></p> </div> <div class="footer-popup-confirm"> <button class="cancel-confirm-nguyennhieu" data-dismiss="modal" aria-label="Close">Cancel</button> <button class="access-confirm-nguyennhieu" data-dismiss="modal" aria-label="Close">Confirm</button> </div></div>`);
	$(".popup-nguyennhieu").html(content);
	$("#popup-confirm").modal("show");
};

function photoZone(eDrag, iDrag, eLoad) {
	if ($(eDrag).length) {
		$(eDrag).on("dragover", function () {
			$(this).addClass("drag-over");
			return false;
		});
		$(eDrag).on("dragleave", function () {
			$(this).removeClass("drag-over");
			return false;
		});
		$(eDrag).on("drop", function (e) {
			e.preventDefault();
			$(this).removeClass("drag-over");
			var lengthZone = e.originalEvent.dataTransfer.files.length;
			if (lengthZone == 1) {
				$(iDrag).prop("files", e.originalEvent.dataTransfer.files);
				readImage($(iDrag), eLoad);
			} else if (lengthZone > 1) {
				notifyDialog("Bạn chỉđược chọn 1 hình ảnh để upload");
				return false;
			} else {
				notifyDialog("Dữ liệu không hợp lệ");
				return false;
			}
		});
		$(iDrag).change(function () {
			readImage($(this), eLoad);
		});
	}
};

function readImage(inputFile, elementPhoto) {
	if (inputFile[0].files[0]) {
		if (inputFile[0].files[0].name.match(/.(jpg|jpeg|png|gif|svg|webp)$/i)) {
			var size = parseInt(inputFile[0].files[0].size) / 1024;
			if (size <= 4096) {
				var reader = new FileReader();
				reader.onload = function (e) {
					$(elementPhoto).attr('src', e.target.result);
				};
				reader.readAsDataURL(inputFile[0].files[0]);
			} else {
				notifyDialog("Dung lượng hình ảnh lớn. Dung lượng cho phép <= 4MB ~ 4096KB");
				return false;
			};
		} else {
			notifyDialog("Hình ảnh không hợp lệ");
			return false;
		};
	} else {
		notifyDialog("Dữ liệu không hợp lệ");
		return false;
	};
};

function formatMoney(amount) {
	if (amount !== null && amount !== undefined) {
		return amount.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ".") + "đ";
	} else {
		return "0đ";
	}
};
