$.fn.exists = function () {
	return this.length;
};
SIEUTHICODE.AltImages = function () {
	$('img').each(function (index, element) {
		if (!$(this).attr('alt') || $(this).attr('alt') == '') {
			$(this).attr('alt', WEBSITE_NAME);
		};
	});
};
SIEUTHICODE.FixMenu = function () {
	if ($(window).scrollTop() > 50) {
		$("#menu").addClass('fixing');
		$("#menu-mobile").addClass("fixing");
	} else {
		$("#menu").removeClass('fixing');
		$("#menu-mobile").removeClass("fixing");
	}
	$(window).scroll(function () {
		if ($(window).scrollTop() > 50) {
			$("#menu").addClass('fixing');
			$("#menu-mobile").addClass("fixing");
			$("#search-mobile-hidden").removeClass("fixing");
		} else {
			$("#menu").removeClass('fixing');
			$("#menu-mobile").removeClass("fixing");
		}
	});
};
SIEUTHICODE.ToogleCart = function () {
	$(".background-cart").click(function () {
		toggleCart();
	});
	$(".cart-toggle").click(function () {
		toggleCart();
	});
};
SIEUTHICODE.Mmenu = function () {
	$(".background-mmenu").click(function () {
		toggleMenu();
	});
	$(".menu-toggle").click(function () {
		toggleMenu();
	});
	const navExpand = [].slice.call(document.querySelectorAll('.mmenu ul li'));
	const backLink = `<li class="nav-item"> <p class="nav-link nav-back-link"> ${LANG['back']} </p> </li>`;
	navExpand.forEach(item => {
		const subMenu = item.querySelector('ul');
		if (subMenu) {
			item.querySelector('p').classList.add("nav-expand-link");
			subMenu.classList.add("nav-expand-content");
			item.querySelector('.nav-expand-content').insertAdjacentHTML('afterbegin', backLink);
			item.querySelector('p').addEventListener('click', () => item.classList.add('active'));
			item.querySelector('.nav-back-link').addEventListener('click', () => item.classList.remove('active'));
		}
	});
};
SIEUTHICODE.Toc = function () {
	if ($(".mce-toc").exists()) {
		$('.mce-toc').find('a').click(function (e) {
			e.preventDefault();
			var x = $(this).attr('href');
			goToByScroll(x);
		});
	};
};
SIEUTHICODE.Popup = function () {
	if ($("#popup").exists()) {
		$('#popup').modal('show');
	};
	$('.open-modals-auth').click(function (e) {
		e.preventDefault();
		const modal = $(this).attr("data-class");
		$(".form-auth").removeClass("active");
		$(".form-auth." + modal).addClass("active");
		$("#filter-lsnapthe").modal("hide");
		$(".toggle-auth").modal("show");
	});
	$(".toogle-form-auth").click(function (e) {
		e.preventDefault();
		const action = $(this).attr("data-action");
		$(".form-auth").removeClass("active");
		$(".form-auth." + action).addClass("active");
	});
	if ($(".open-popup-user").exists()) {
		$(".open-popup-user").click(function () {
			const id = $(this).attr("data-id");
			const act = $(this).attr("data-act");
			$.ajax({
				url: 'ajax/ajax_user.php',
				type: "POST",
				async: true,
				data: {
					id: id,
					act: act
				},
				success: function (result) {
					$(".container-modals-user").html(result);
					$('.select2').each(function () {
						const id = $(this).attr("id");
						$("#" + id).select2();
					});
					if ($(".multiselect").exists()) {
						$(".multiselect").SumoSelect();
					};
					nguyennhieMCE();
					ValidationFormSelf("validation-user");
				}
			});
			$("#popup-user").modal('show');
		});
	};
};
