SIEUTHICODE.ratejs = function () {
	$(document).ready(function () {
		var rating_data = 0;
		$('#add_review').click(function () {
			$('#review_modal').modal('show');
		});
		$(document).on('mouseenter', '.submit_star', function () {
			var rating = $(this).data('rating');
			reset_background();
			for (var count = 1; count <= rating; count++) {
				$('#submit_star_' + count).addClass('text-warning');
			}
		});
		$(document).on('mouseleave', '.submit_star', function () {
			reset_background();
			for (var count = 1; count <= rating_data; count++) {
				$('#submit_star_' + count).removeClass('star-light');
				$('#submit_star_' + count).addClass('text-warning');
			}
		});
		$(document).on('click', '.submit_star', function () {
			rating_data = $(this).data('rating');
		});
		$('#save_review').click(function () {
			var user_name = $('#ten_review').val();
			var user_review = $('#noidung_review').val();
			if (user_name == '' || user_review == '' || rating_data == 0) {
				alertWarning(LANG['warning'], LANG['vuilongdiendayduthongtin']);
				return false;
			} else {
				$.ajax({
					url: "ajax/ajax_rating.php",
					method: "POST",
					data: {
						id: id,
						rate: rating_data,
						ten: user_name,
						noidung: user_review
					},
					success: function (data) {
						$('#review_modal').modal('hide');
						load_rating_data(id);
					}
				})
			}
		});
		if ($("#review_content").exists()) {
			load_rating_data(id);
		};
		if ($(".noidung-product-content").exists()) {
			$(".noidung-product-content").each(function () {
				if ($(this).height() > 505) {
					$(this).addClass("active");
					$(".div-view-noidung").show();
				}
			});
			$(".div-view-noidung").click(function () {
				$(this).hide();
				$(".noidung-product-content").removeClass("active");
			});
		};
	});
};
