SIEUTHICODE.Cart = function () {
	$(document).ready(function () {
		var wait = false;
		if ($('.order-cart').exists()) {
			getOrder();
			getTotalCart();
		};
		if (!$("#section-nickgame.teamplate2").exists()) {
			if ($(".mySwiper").exists()) {
				var swiper = new Swiper(".mySwiper.product-detail", {
					loop: true,
					grabCursor: false,
					mousewheel: false,
					keyboard: {
						enabled: true,
					},
					spaceBetween: 10,
					slidesPerView: "auto",
					freeMode: true,
					watchSlidesProgress: true,
				});
				var swiper2 = new Swiper(".mySwiper2.product-detail", {
					loop: true,
					spaceBetween: 0,
					keyboard: {
						enabled: true,
					},
					navigation: {
						nextEl: ".swiper-button-next",
						prevEl: ".swiper-button-prev",
					},
					thumbs: {
						swiper: swiper,
					},
				});
			} else {
				var swiper2 = new Swiper(".mySwiper2.product-detail", {
					loop: true,
					spaceBetween: 10,
					keyboard: {
						enabled: true,
					},
					navigation: {
						nextEl: ".swiper-button-next",
						prevEl: ".swiper-button-prev",
					}
				});
			};
		}
		$('.checkbox_attribute').change(function () {
			var groupName = $(this).attr('name');
			if ($(this).prop('checked')) {
				$('input[type="checkbox"].checkbox_attribute[name="' + groupName + '"]').not(this).prop('checked', false);
			};
		});
		$('.picker').change(function () {
			var groupName = $(this).attr('name');
			if ($(this).prop('checked')) {
				$('input[type="checkbox"].picker[name="' + groupName + '"]').not(this).prop('checked', false);
			};
			const checkedOption = $('input.picker:checked');
			const id = $(this).attr("data-photo");
			let data = {
				cmd: 'update-detail',
				groupName: groupName,
				id: id,
				option: {}
			};
			checkedOption.each(function () {
				const value = $(this).val();
				const name_options = $(this).attr("data-options");
				data.option = {
					...data.option,
					[name_options]: value
				};
			});
			if (Object.keys(data.option).length > 0) {
				$.ajax({
					url: 'ajax/ajax_cart.php',
					type: "POST",
					async: true,
					data: data,
					success: function (result) {
						const response = JSON.parse(result, true);
						const slides = swiper2.slides;
						for (let i = 0; i < slides.length; i++) {
							if (slides[i].getAttribute('data-url') === response.photo) {
								swiper2.slideTo(i);
								break;
							}
						}
						if (response.type == 2) {
							$.each(response.active, (key, value) => {
								$("." + key).each(function () {
									if (value.includes($(this).val())) {
										$(this).prop("disabled", false);
									} else {
										$(this).prop("disabled", true);
									}
								});
							});
							$(".add-cart-now").addClass("disable");
							if ($(".radio-typebuy").exists()) {
								const typebuy = $(".select-typebuy").attr("data-typebuy");
								const active = response.active['option_' + typebuy];
								if (active) {
									$(".radio-option_" + typebuy).each(function () {
										if (active.includes($(this).val())) {
											$(this).prop("disabled", false);
										} else {
											$(this).prop("disabled", true);
											$(this).prop("selected", false);
										}
									});
									$('.select2').each(function () {
										const id = $(this).attr("id");
										$("#" + id).select2();
									});
									const checkrent = $("#option_rent option:not([disabled])").length;
									if (checkrent == 0) {
										$("#radio-thue").prop("disabled", true);
									} else {
										$("#radio-thue").prop("disabled", false);
									}
									const checkbuy = $("#option_buy option:not([disabled])").length;
									if (checkbuy == 0) {
										$("#radio-buy").prop("disabled", true);
									} else {
										$("#radio-buy").prop("disabled", false);
									}
								}
							};
						} else {
							$.each(response.active, (key, value) => {
								$("." + key).each(function () {
									if (value.includes($(this).val())) {
										$(this).prop("disabled", false);
									} else {
										$(this).prop("disabled", true);
									}
								});
							});
							$("#change-gia").text(response.gia);
							$("#change-giamoi").text(response.giamoi);
							$("#change-giakm").text("-" + response.giakm + "%");
							$("#sold-value").text(response.sold);
							$("#change-quantity").text(response.quantity);
							$("#add-cart").attr("max", response.quantity);
							$(".add-cart-now").removeClass("disable");
							const tb = $(".radio-typebuy:checked").val();
							if (tb == 3) {
								$("#giathuemoi").text(response.giamoi);
								const text = $("#option_rent option:selected").text();
								$(".ten-optiontypebuy").text(text);
							} else {
								$("#giamuamoi").text(response.giamoi);
							}
							if ($(".radio-typebuy").exists()) {
								const typebuy = $(".select-typebuy").attr("data-typebuy");
								const active = response.active['option_' + typebuy];
								if (active) {
									$(".radio-option_" + typebuy).each(function () {
										if (active.includes($(this).val())) {
											$(this).prop("selected", true);
											$(this).prop("disabled", false);
										} else {
											$(this).prop("disabled", true);
											$(this).prop("selected", false);
										}
									});
									$('.select2').each(function () {
										const id = $(this).attr("id");
										$("#" + id).select2();
									});
									const checkrent = $("#option_rent option:not([disabled])").length;
									if (checkrent == 0) {
										$("#radio-thue").prop("disabled", true);
									} else {
										$("#radio-thue").prop("disabled", false);
									}
									const checkbuy = $("#option_buy option:not([disabled])").length;
									if (checkbuy == 0) {
										$("#radio-buy").prop("disabled", true);
									} else {
										$("#radio-buy").prop("disabled", false);
									}
								}
							};
						}
					}
				});
			} else {
				$(".picker").each(function () {
					$(this).prop("disabled", false);
				});
				$("#change-gia").text($("#change-gia").attr("data-default"));
				$("#change-giamoi").text($("#change-giamoi").attr("data-default"));
				$("#change-giakm").text($("#change-giakm").attr("data-default"));
				$("#change-quantity").text($("#change-quantity").attr("data-default"));
				$(".add-cart-now").addClass("disable");
				$("#giathuemoi").text($("#giathuemoi").attr("data-default"));
				$("#giamuamoi").text($("#giamuamoi").attr("data-default"));
			};
		});
		$("body").on("change", ".p-cart", function () {
			if ($(this).val() < 1) {
				$(this).val(1);
			};
			if (Number($(this).val()) > Number($(this).attr("max"))) {
				$(this).val($(this).attr("max"));
				alertDancer(LANG['productsolderror'], LANG['noquantitypctd']);
			};
		});
		$("body").on("change", ".quantity-change-event", function () {
			const code = $(this).attr("data-code");
			const qty = $(this).val();
			$("#cart").addClass("loaddding");
			if ($(".form-cart").exists()) {
				$(".form-cart").addClass("loadding");
			};
			if ($(".form-order").exists()) {
				$(".form-order").addClass("loadding");
			};
			if (wait) {
				clearTimeout(wait);
				wait = setTimeout(() => {
					updateQtyCart(code, qty, code);
					wait = false;
				}, 1000);
			} else {
				wait = setTimeout(() => {
					updateQtyCart(code, qty, code);
					wait = false;
				}, 1000);
			};
		});
		$("body").on("click", ".minus-input", function (e) {
			e.preventDefault();
			const element = $(this).attr("data-for");
			$("." + element).val(Number($('.' + element).val()) - 1);
			$("." + element).trigger('change');
		});
		$("body").on("click", ".plus-input", function (e) {
			e.preventDefault();
			const element = $(this).attr("data-for");
			$("." + element).val(Number($('.' + element).val()) + 1);
			$("." + element).trigger('change');
		});
		if ($(".radio-typebuy").exists()) {
			const value = $(".radio-typebuy:checked").val();
			let option = 0;
			if (value == 3) {
				option = $("#option_rent").val();
			} else {
				option = $("#option_buy").val();
			}
			$("#pick_" + option).prop("checked", true);
			$("#pick_" + option).trigger("change");
			$(".radio-typebuy").change(function () {
				const value = $(".radio-typebuy:checked").val();
				let option = 0;
				if (value == 3) {
					option = $("#option_rent").val();
				} else {
					option = $("#option_buy").val();
				}
				$("#pick_" + option).prop("checked", true);
				$("#pick_" + option).trigger("change");
			});
			$("#option_rent").change(function () {
				const option = $("#option_rent").val();
				$("#pick_" + option).prop("checked", true);
				$("#pick_" + option).trigger("change");
			});
			$("#option_buy").change(function () {
				const option = $("#option_buy").val();
				$("#pick_" + option).prop("checked", true);
				$("#pick_" + option).trigger("change");
			});
		}
	});
	$("body").on("click", ".delete-item-cart_", function () {
		const code = $(this).attr("data-code");
		MSalert.principal({
			icon: 'warning',
			title: LANG['warning'],
			description: LANG['areyouwanttodelete'],
			extra: LANG['yesiscontinue'],
			button: true,
		}).then(result => {
			if (result == true) {
				$.ajax({
					url: 'ajax/ajax_cart.php',
					type: "POST",
					async: true,
					data: {
						code: code,
						cmd: 'delete-cart'
					},
					success: function (result) {
						getTotalCart();
						$(".items-cart-" + code).remove();
						$(".items-order-" + code).remove();
					}
				});
			};
		});
	});
	$("body").on("click", ".add-cart-now", function () {
		var id = $(this).data("id");
		var action = $(this).data("action");
		if ($("input.picker").exists() || $("input.checkbox_attribute").exists()) {
			if ($(this).hasClass("disable")) {
				alertWarning(LANG['warning'], LANG['checkallattributes']);
				return;
			};
		}
		if ($("input.checkbox_attribute").exists()) {
			if ($(this).hasClass("warning")) {
				if (!$("input.checkbox_attribute:checked").exists()) {
					alertWarning(LANG['warning'], LANG['checkallattributes']);
					return;
				};
			};
		};
		var quantity = ($(".add-cart").val()) ? $(".add-cart").val() : 1;
		let data = {
			cmd: 'add-cart',
			id: id,
			quantity: quantity,
			option: {}
		};
		const checkedOption1 = $('input.picker:checked');
		checkedOption1.each(function () {
			const value = $(this).val();
			const name_options = $(this).attr("data-options");
			data.option = {
				...data.option,
				[name_options]: value
			};
		});
		const checkedOption2 = $('input.checkbox_attribute:checked');
		checkedOption2.each(function () {
			const value = $(this).val();
			const name_options = $(this).attr("data-options");
			data.option = {
				...data.option,
				[name_options]: value
			};
		});
		if (id) {
			$.ajax({
				url: 'ajax/ajax_cart.php',
				type: "POST",
				dataType: 'html',
				async: true,
				data: data,
				success: function (result) {
					if (action == 'add') {
						toggleCart();
					} else if (action == 'payment') {
						window.location = CONFIG_BASE + "gio-hang";
					}
				}
			});
		}
	});
	$(".open-address").click(function () {
		$(".choose-address").toggle();
	});
	$("#tangqua").change(function () {
		$(".tangquabox").toggle();
		if ($(this).prop('checked')) {
			$("#tennguoinhan").attr("required", true);
			$("#tennguoigui").attr("required", true);
			$("#thongdiep").attr("required", true);
		} else {
			$("#tennguoinhan").attr("required", false);
			$("#tennguoigui").attr("required", false);
			$("#thongdiep").attr("required", false);
		};
	});
	$("body").on("change", ".select-city-cart", function () {
		var id = $(this).val();
		load_district(id);
	});
	$("body").on("change", ".select-district-cart", function () {
		var id = $(this).val();
		load_wards(id);
	});
	if ($(".change-address-no").exists()) {
		$(".change-address-no").click(function () {
			const id = $(this).attr("data-id");
			$('.address-load').addClass("loadding");
			$.ajax({
				type: 'post',
				url: 'ajax/ajax_address_private.php',
				async: true,
				data: {
					id: id
				},
				success: function (result) {
					$(".address-load").html(result);
					$('.select2').each(function () {
						const id = $(this).attr("id");
						$("#" + id).select2();
					});
					$('.address-load').removeClass("loadding");
					$(".open-address").click();
				}
			});
		});
	};
	$("body").on("click", ".ajax_coupons", function (e) {
		const code = $(this).attr("data-code");
		$.ajax({
			url: 'ajax/ajax_cart.php',
			type: "POST",
			async: true,
			data: {
				cmd: 'load-coupons',
				code: code,
			},
			success: function (result) {
				$(".box-apply-code").html(result);
				$("#coupons_modal").modal("show");
			}
		});
	});
	$("body").on("click", ".copyButton", function () {
		var text = $(this).attr("data-text");
		navigator.clipboard.writeText(text);
		if (!$(this).hasClass("active")) {
			$(".copyButton").removeClass("active");
			$(this).addClass("active");
			alertSuccess(LANG['tingting'], LANG['dacopynoidung']);
		}
	});
	$("#form-order").on('submit', function (e) {
		const form = document.getElementById("form-order");
		if (form.checkValidity()) {
			toggle_loadding();
			return;
		} else {
			return;
		}
	});
};
SIEUTHICODE.scrollSmooth = function () {
	$(document).ready(function () {
		if (!$(".container-nguyennhieu").exists()) {
			const lenis = new Lenis();
			lenis.on('scroll', ScrollTrigger.update);
			gsap.ticker.add((time) => {
				lenis.raf(time * 1000);
			});
			gsap.ticker.lagSmoothing(0);
		}
	});
};
SIEUTHICODE.swiper = function () {
	$(document).ready(function () {
		if ($(".swiper-slide-slide").exists()) {
			const slideshow = new Swiper(".swiper-slide-slide", {
				loop: true,
				mousewheel: false,
				grabCursor: false,
				spaceBetween: 0,
				slidesPerView: 1,
				autoplay: {
					delay: 10000,
					disableOnInteraction: false,
				},
				navigation: {
					hide: true,
					nextEl: ".swiper-slide-slide-btn-next",
					prevEl: ".swiper-slide-slide-btn-prev",
				},
			});
		};
	});
};
