	$(document).ready(function () {
		$.ajax({
			url: "/model/getbanks",
			type: "GET",
			dataType: "json",
			success: function (response) {
				if (!Array.isArray(response) || response.length === 0) {
					$("#bank-options").html('<p class="text-muted">Chưa cấu hình tài khoản ngân hàng.</p>');
					return;
				}

				let bankOptions = "";
				response.forEach((bank, index) => {
					bankOptions += `
                    <div class="container-radio-banking">
                        <input type="radio" class="radio-banking select-nganhang-banking" name="nganhang" 
                            id="radio-banking${bank.id}" value="${bank.id}" ${index === 0 ? "checked" : ""} required>
                        <label for="radio-banking${bank.id}">
                            <img class="lazyload" src="/assets/images/lazyload.gif"  data-src="${bank.logo}" alt="${bank.bank_name}">
                        </label>
                    </div>`;
				});
				$("#bank-options").html(bankOptions);
				updateBankInfo(response[0]);
				$("input[name='nganhang']").change(function () {
					let selectedBank = response.find(bank => String(bank.id) === String($(this).val()));
					updateBankInfo(selectedBank);
				});
			}
		});

		function updateBankInfo(bank) {
			if (!bank) {
				return;
			}
			$("#account-number").text(bank.account_number);
			$("#account-name").text(bank.account_name);
			$("#bank-name").text(bank.bank_name);
			$("#transfer-content").text(bank.transfer_content);
			$("#content").html(bank.content);
			let qrCode = $("#qr-code");
			qrCode.attr("data-src", bank.qr_code);
			qrCode.addClass("lazyload");
			$("#copy-account").attr("data-text", bank.account_number);
			$("#copy-transfer").attr("data-text", bank.transfer_content);
		}
	});
