	$("body").on("change", "#wheel_range", function (e) {
		const money = $(this).attr("data-money");
		const quantity = $(this).val();
		let result = money * quantity;
		$(".money-display").html(formatMoney(result));
		if ($(".radio-member-payments").exists()) {
			$('input[name="radio-payments"]').attr('data-giamoi', result);
			const dataMoney = $('input[name="radio-payments"]:checked').attr('data-money');
			if (Number(dataMoney) < result) {
				$(".confirm-dichvugame").addClass("d-none");
				$(".naptien-dichvugame").removeClass("d-none");
			} else {
				$(".naptien-dichvugame").addClass("d-none");
				$(".confirm-dichvugame").removeClass("d-none");
			}
			if (Number($("#radio-payments2").attr("data-money")) < result) {
				$("#radio-payments2").attr("disabled", "disabled");
			} else {
				$("#radio-payments2").attr("disabled", false);
			}
		}
	});
	$("body").on("change", ".checkbox-dichvugame", function (e) {
		const checkboxes = document.querySelectorAll('.checkbox-dichvugame');
		let result = 0;
		let isChecked = false;
		$(".content-goi-dichvugame").html("");
		checkboxes.forEach(function (checkbox) {
			if (checkbox.checked) {
				const money = checkbox.getAttribute('data-money');
				const ten = checkbox.getAttribute('data-ten');
				const $element = `<div class="line-thongtin"> <p>Gói</p> <p>${ten}</p> </div>`;
				result += Number(money);
				isChecked = true;
				$(".content-goi-dichvugame").append($element);
			}
		});
		if (!isChecked) {
			$(".line-error-dichvugame").show();
			checkboxes.forEach(function (checkbox) {
				checkbox.setAttribute('required', 'required');
			});
		} else {
			checkboxes.forEach(function (checkbox) {
				checkbox.removeAttribute('required');
			});
			$(".line-error-dichvugame").hide();
		}
		$(".money-display").html(formatMoney(result));
		if ($(".radio-member-payments").exists()) {
			$('input[name="radio-payments"]').attr('data-giamoi', result);
			const dataMoney = $('input[name="radio-payments"]:checked').attr('data-money');
			if (Number(dataMoney) < result) {
				$(".confirm-dichvugame").addClass("d-none");
				$(".naptien-dichvugame").removeClass("d-none");
			} else {
				$(".naptien-dichvugame").addClass("d-none");
				$(".confirm-dichvugame").removeClass("d-none");
			}
			if (Number($("#radio-payments2").attr("data-money")) < result) {
				$("#radio-payments2").attr("disabled", "disabled");
			} else {
				$("#radio-payments2").attr("disabled", false);
			}
		}
	});
