					if (result.status == 6 || result.status == 8 || result.status == 4) {
						alertDancer("Thông báo nạp thẻ", "Gửi thẻ thành công. Hệ thống đang xử lý thẻ. Tải lại trang hoặc kiểm tra trạng thái thẻ trong lịch sử nạp thẻ");
					} else if (result.status == 5) {
						alertSuccess("Thông báo nạp thẻ", result.message);
					} else if (result.status == 9) {
						alertDancer("Thông báo nạp thẻ", result.message);
					} else {
						alertDancer("Thông báo nạp thẻ", result.message);
					}
