	$("body").on("click", ".get_maxacthuc_2fa", function (e) {
		const maxacthuc = $(this).attr("data-maxacthuc");
		const url__submit = 'ajax/ajax_maxacthuc.php';
		$.ajax({
			url: url__submit,
			type: 'POST',
			data: {
				maxacthuc: maxacthuc
			},
			success: function (res) {
				const result = JSON.parse(res);
				if (result.token) {
					$(".text-maxacthuc").html(result.token);
					$(".text-maxacthuc").removeClass("d-none");
					$(".copy-maxacthuc").attr("data-text", result.token);
					$(".copy-maxacthuc").removeClass("d-none");
					$(".copy-maxacthuc").removeClass("active");
					$(".get_maxacthuc_2fa").addClass("active");
				} else {
					$(".text-maxacthuc").addClass("d-none");
					$(".copy-maxacthuc").addClass("d-none");
					$(".copy-maxacthuc").removeClass("active");
					$(".get_maxacthuc_2fa").removeClass("active");
				}
			},
		});
	});
