SIEUTHICODE.componentInput = function () {
	$(document).ready(function () {
		$(".eye-input").click(function () {
			const inputPassword = $(this).prev('input');
			inputPassword.attr('type', (inputPassword.attr('type') === 'password') ? 'text' : 'password');
			$(this).toggleClass('hide');
		});
		$('input.input-text').each(function () {
			const maxLength = $(this).attr('max');
			if (this.type === 'hidden' || maxLength === undefined) {
				return;
			}
			const inputValue = $(this).val();
			const countInput = $(this).closest('.input-element').find('.count-input');
			countInput.text(`${inputValue.length}/${maxLength}`);
		});
		$(".input-code-card").on("keypress", function (e) {
			const keyCode = e.which;
			if (keyCode < 48 || keyCode > 57) {
				e.preventDefault();
			}
		});
		$("input.input-text").on("input", function () {
			const maxLength = $(this).attr('max');
			if (this.type === 'hidden' || maxLength === undefined) {
				return;
			}
			const inputValue = $(this).val();
			if (inputValue.length > Number(maxLength)) {
				const truncatedValue = inputValue.slice(0, maxLength);
				$(this).val(truncatedValue);
				return;
			}
			const countInput = $(this).closest('.input-element').find('.count-input');
			countInput.text(`${inputValue.length}/${maxLength}`);
		});
		$(".input-username-register").on("input", function () {
			let inputValue = $(this).val();
			inputValue = inputValue.replace(/[^\w]/g, '').toLowerCase();
			$(this).val(inputValue);
		});
		$(".icon-quantity").on("click", function () {
			const input = $(this).closest('.input-element').find('input');
			const min = input.attr("min");
			const max = input.attr("max");
			if ($(this).hasClass("plus")) {
				let result = Number(input.val()) + 1;
				if (result > Number(max)) result = max;
				input.val(result);
			} else {
				let result = Number(input.val()) - 1;
				if (result < Number(min)) result = min;
				input.val(result);
			};
			input.trigger('change');
		});
		$("input.input-quantity").change(function (e) {
			let inputValue = $(this).val();
			inputValue = Number(inputValue.replace(/[^0-9]/g, ''));
			const min = $(this).attr("min");
			const max = $(this).attr("max");
			let val = 0;
			if (inputValue > max) {
				val = max;
			} else if (inputValue < min) {
				val = min;
			} else {
				val = inputValue;
			};
			$(this).val(val);
		});
		$('textarea.textarea').each(function () {
			const inputValue = $(this).val();
			const maxLength = $(this).attr('max');
			const countInput = $(this).closest('.input-textarea').find('.count-textarea');
			countInput.text(`${inputValue.length}/${maxLength}`);
		});
		$("textarea.textarea").on("input", function () {
			const inputValue = $(this).val();
			const maxLength = $(this).attr('max');
			const countInput = $(this).closest('.input-textarea').find('.count-textarea');
			countInput.text(`${inputValue.length}/${maxLength}`);
		});
		$("input.input-date-singe").each(function () {
			const drops = $(this).attr("data-drops");
			$(this).daterangepicker({
				singleDatePicker: true,
				timePicker: true,
				timePicker24Hour: true,
				timePickerSeconds: true,
				showDropdowns: true,
				minYear: 1901,
				maxYear: parseInt(moment().format('YYYY'), 10),
				opens: "right",
				drops: drops ? drops : "auto",
				parentEl: $(this).closest(".input-element"),
				locale: {
					cancelLabel: 'Huỷ',
					applyLabel: 'Áp dụng',
					format: 'YYYY/MM/DD',
				},
				lang: 'vi',
			});
		});
		if ($('input[name="from_date"]').attr("data-val") == "") $('input[name="from_date"]').val('');
		$(".input-date-multiple").each(function () {
			$(this).daterangepicker({
				timePicker: true,
				timePicker24Hour: true,
				timePickerSeconds: true,
				showDropdowns: true,
				alwaysShowCalendars: true,
				maxSpan: {
					"days": 175
				},
				minYear: 1901,
				linkedCalendars: false,
				maxYear: parseInt(moment().format('YYYY'), 10),
				opens: "right",
				drops: "auto",
				parentEl: $(this).closest(".input-element"),
				locale: {
					cancelLabel: 'Huỷ',
					applyLabel: 'Áp dụng',
					format: 'YYYY/MM/DD',
				},
				lang: 'vi',
			});
		});
		nguyennhieMCE();
		update_textarea();
		select_nguyennhieu();
		photoZone("#zone-avatar-account", "#input-avatar-account", ".avatar-account img");
		$(".zone-file").click(function () {
			const input = $(this).attr("for");
			$("#" + input).click();
		});
	});
};
