function zoom(e) {
	var zoom = e.currentTarget;
	e.offsetX ? offsetX = e.offsetX : offsetX = e.touches[0].pageX;
	e.offsetY ? offsetY = e.offsetY : offsetX = e.touches[0].pageX;
	x = (offsetX / zoom.offsetWidth) * 100;
	y = (offsetY / zoom.offsetHeight) * 100;
	zoom.style.backgroundPosition = x + "% " + y + "%";
};
$(document).ready(function () {
	"use strict";
	if ($(".progress-wrap").exists()) {
		var progressPath = document.querySelector('.progress-wrap path');
		var pathLength = progressPath.getTotalLength();
		progressPath.style.transition = progressPath.style.WebkitTransition = 'none';
		progressPath.style.strokeDasharray = pathLength + ' ' + pathLength;
		progressPath.style.strokeDashoffset = pathLength;
		progressPath.getBoundingClientRect();
		progressPath.style.transition = progressPath.style.WebkitTransition = 'stroke-dashoffset 10ms linear';
		var updateProgress = function () {
			var scroll = $(window).scrollTop();
			var height = $(document).height() - $(window).height();
			var progress = pathLength - (scroll * pathLength / height);
			progressPath.style.strokeDashoffset = progress;
		};
		updateProgress();
		$(window).scroll(updateProgress);
		var offset = 150;
		var duration = 550;
		$(window).on('scroll', function () {
			if ($(this).scrollTop() > offset) {
				$('.progress-wrap').addClass('active-progress');
			} else {
				$('.progress-wrap').removeClass('active-progress');
			}
		});
		$('.progress-wrap').on('click', function (event) {
			event.preventDefault();
			$('html, body').animate({
				scrollTop: 0
			}, duration);
			return false;
		});
	}
});
$(document).ready(function () {
	var url = window.location.pathname.replace(/\/$/, ''); // Xóa dấu "/" cuối cùng
	var isActiveSet = false; // Biến kiểm tra đã set active hay chưa

	// Xóa class active trước khi thêm
	$('.item-link').removeClass('active');

	$('.item-link').each(function () {
		var href = $(this).attr('href').replace(/\/$/, ''); // Xóa dấu "/" cuối cùng trong href

		// Kiểm tra khớp URL chính xác
		if (url === href) {
			$(this).addClass('active');
			isActiveSet = true;
		}
	});

	// Nếu không có mục nào được active, mặc định active mục đầu tiên
	if (!isActiveSet) {
		$('.item-link:first').addClass('active');
	}
});

$(document).ready(function () {
	var url = window.location.pathname;
	var urlRegExp = new RegExp("^" + url.replace(/\/$/, '') + "$");
	$('.menu-item-footer').removeClass('active');
	var isActiveSet = false;
	$('.menu-item-footer a').each(function () {
		var href = $(this).attr('href').replace(/\/$/, '');

		if (urlRegExp.test(href)) {
			$(this).closest('.menu-item-footer').addClass('active');
			isActiveSet = true;
		}
	});
	if (!isActiveSet) {
		$('.menu-item-footer:first').addClass('active');
	}
});


$(document).ready(function () {
	let items = document.querySelectorAll('.img-photo-user');
	let draggedItem = null;
	items.forEach(item => {
		item.addEventListener('dragstart', () => {
			draggedItem = item;
		});
		item.addEventListener('dragover', (e) => {
			e.preventDefault();
		});
		item.addEventListener('drop', () => {
			if (draggedItem !== null) {
				const currentIndex = Array.from(items).indexOf(item);
				const initialIndex = Array.from(items).indexOf(draggedItem);
				items[currentIndex].parentNode.insertBefore(draggedItem, items[currentIndex]);
				items = document.querySelectorAll('.img-photo-user');
				draggedItem = null;
			}
		});
	});
});